sp_ListarFormaPagamento	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarFormaPagamento`(IN p_idEmpresa INT)\nBEGIN\n\n    SELECT idFormaPagamento, nome, fAtivo\n\n    FROM FormaPagamento\n\n    WHERE idEmpresa = p_idEmpresa AND fAtivo = 1\n\n    ORDER BY nome;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
